using Microsoft.EntityFrameworkCore;

namespace SocialService.Data;

public static class ContentRules
{
    public const int MaxAuthorNameLength = 32;
    public const int MaxPostLength = 2000;
    public const int MaxCommentLength = 1000;
    public const int MaxSearchLength = 100;
    public const int DefaultPageSize = 20;
    public const int MaxPageSize = 50;

    /// <summary>Author id used for content generated by the game engine (real user ids start at 1).</summary>
    public const int SystemAuthorId = 0;
}

public sealed class Post
{
    public int Id { get; set; }
    public int AuthorId { get; set; }
    public required string AuthorName { get; set; }
    public required string Content { get; set; }
    public bool IsTrending { get; set; }
    public DateTime CreatedAt { get; set; }
    public List<Comment> Comments { get; set; } = [];
}

public sealed class Comment
{
    public int Id { get; set; }
    public int PostId { get; set; }
    public Post? Post { get; set; }
    public int AuthorId { get; set; }
    public required string AuthorName { get; set; }
    public required string Content { get; set; }
    public DateTime CreatedAt { get; set; }
}

public sealed class SocialDbContext(DbContextOptions<SocialDbContext> options) : DbContext(options)
{
    public DbSet<Post> Posts => Set<Post>();
    public DbSet<Comment> Comments => Set<Comment>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Post>(post =>
        {
            post.Property(p => p.AuthorName).HasMaxLength(ContentRules.MaxAuthorNameLength);
            post.Property(p => p.Content).HasMaxLength(ContentRules.MaxPostLength);
            post.HasIndex(p => p.CreatedAt);
            post.HasMany(p => p.Comments)
                .WithOne(c => c.Post)
                .HasForeignKey(c => c.PostId)
                .OnDelete(DeleteBehavior.Cascade);
        });

        modelBuilder.Entity<Comment>(comment =>
        {
            comment.Property(c => c.AuthorName).HasMaxLength(ContentRules.MaxAuthorNameLength);
            comment.Property(c => c.Content).HasMaxLength(ContentRules.MaxCommentLength);
            comment.HasIndex(c => new { c.PostId, c.CreatedAt });
        });
    }
}
